import React, { useLayoutEffect, useState } from 'react';
import { Row } from 'react-table';
import useResizeObserver from 'use-resize-observer';

import { Flex } from '../../layouts-core/flex/Flex.js';
import { useDataTableSlots } from '../hooks/useDataTableSlots.js';

// #region Typings
type TableActionsRenderedProps = {
  dataTableChildren: React.ReactNode;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  currentSelectedRows: Row<any>[];
};
// #endregion Typings

/**
 * This component is used to conditionaly render the Table actions and SelectedRowsActions sub-components
 * to toggle their visibility state and handle the height of their parent element
 * @internal
 */
export const _TableActionsRenderer = (props: TableActionsRenderedProps) => {
  const { dataTableChildren, currentSelectedRows } = props;
  const slots = useDataTableSlots(dataTableChildren);

  const [actionsHeight, setActionsHeight] = useState<
    number | string | undefined
  >('auto');

  const { ref: selectedRowsActionsRef, height: selectedRowsActionsHeight } =
    useResizeObserver<HTMLDivElement>();
  const { ref: tableActionsRef, height: tableActionsHeight } =
    useResizeObserver<HTMLDivElement>();

  useLayoutEffect(() => {
    const maxHeight =
      (selectedRowsActionsHeight ?? 0) > (tableActionsHeight ?? 0)
        ? selectedRowsActionsHeight
        : tableActionsHeight;
    if (maxHeight !== 0) {
      setActionsHeight(maxHeight);
    } else {
      return;
    }
  }, [selectedRowsActionsHeight, tableActionsHeight]);

  return (
    <Flex
      height={actionsHeight}
      style={{ position: 'relative' }}
      flexGrow={1}
      alignItems="flex-end"
    >
      <div
        ref={tableActionsRef}
        style={{
          visibility:
            (slots.selectedRowsActions === null ||
              currentSelectedRows.length === 0) &&
            slots.tableActions
              ? 'visible'
              : 'hidden',
        }}
      >
        {slots.tableActions}
      </div>
      <div
        ref={selectedRowsActionsRef}
        style={{
          position: 'absolute',
          bottom: 0,
          left: 0,
          right: 0,
          visibility: currentSelectedRows.length === 0 ? 'hidden' : 'visible',
        }}
      >
        {slots.selectedRowsActions}
      </div>
    </Flex>
  );
};
